// pages/history/history.js
Page({

  /**
   * 页面的初始数据
   */
  data: {
    historyList: []
  },

  /**
   * 生命周期函数--监听页面加载
   */
  onLoad(options) {
    this.loadHistoryList();
  },

  /**
   * 生命周期函数--监听页面显示
   */
  onShow() {
    // 每次显示时重新加载历史列表
    this.loadHistoryList();
  },

  /**
   * 加载历史作品列表
   */
  loadHistoryList() {
    try {
      const history = wx.getStorageSync('historyImgs') || [];
      console.log('History list:', history);
      this.setData({
        historyList: history
      });
    } catch (e) {
      console.error('Failed to load history:', e);
      wx.showToast({
        title: '加载失败',
        icon: 'none'
      });
    }
  },

  /**
   * 预览作品
   */
  async previewWork(e) {
    const app = getApp();
    const index = e.currentTarget.dataset.index;
    const urls = this.data.historyList.map(h => h.effectUrl);
    const httpUrls = await app.getTempFileURLsAsync(urls);

    wx.previewImage({
      urls: httpUrls,
      current: httpUrls[index]
    });
  },

  /**
   * 长按显示操作菜单
   */
  showActionSheet(e) {
    const index = e.currentTarget.dataset.index;
    const item = this.data.historyList[index];

    wx.showActionSheet({
      itemList: ['预览', '删除'],
      success: (res) => {
        if (res.tapIndex === 0) {
          // 预览
          this.previewWork(e);
        } else if (res.tapIndex === 1) {
          // 删除
          this.confirmDelete(index);
        }
      }
    });
  },

  /**
   * 确认删除
   */
  confirmDelete(index) {
    const item = this.data.historyList[index];
    wx.showModal({
      title: '确认删除',
      content: `确定要删除吗？`,
      confirmColor: '#5d8c87',
      success: (res) => {
        if (res.confirm) {
          this.deleteWork(index);
        }
      }
    });
  },

  /**
   * 删除作品
   */
  deleteWork(index) {
    try {
      const historyList = this.data.historyList;
      historyList.splice(index, 1);

      // 更新存储
      wx.setStorageSync('historyImgs', historyList);

      // 更新页面数据
      this.setData({
        historyList: historyList
      });

      wx.showToast({
        title: '删除成功',
        icon: 'success'
      });
    } catch (e) {
      console.error('Failed to delete work:', e);
      wx.showToast({
        title: '删除失败',
        icon: 'none'
      });
    }
  },

  /**
   * 导航到拼豆页面
   */
  navigateToPindou() {
    wx.navigateTo({
      url: '/pages/pindou/index'
    });
  }
})

