   689→    if (touches.length === 1) {
   690→      const x = touches[0].x,
   691→        y = touches[0].y;
   692→      if (this.cropBox.resizing) {
   693→        // 调整裁剪框大小
   694→        const {
   695→          resizeCorner,
   696→          width,
   697→          height
   698→        } = this.cropBox;
   699→        switch (resizeCorner) {
   700→          case "tl":
   701→            this.cropBox.width = this.cropBox.width - (x - this.cropBox.x);
   702→            this.cropBox.height = this.cropBox.height - (y - this.cropBox.y);
   703→            this.cropBox.x = x;
   704→            this.cropBox.y = y;
   705→            break;
   706→          case "tr":
   707→            this.cropBox.height = this.cropBox.height - (y - this.cropBox.y);
   708→            this.cropBox.y = y;
   709→            this.cropBox.width = x - this.cropBox.x;
   710→            break;
   711→          case "bl":
   712→            this.cropBox.width = this.cropBox.width - (x - this.cropBox.x);
   713→            this.cropBox.height = y - this.cropBox.y;
   714→            this.cropBox.x = x;
   715→            break;
   716→          case "br":
   717→            this.cropBox.width = x - this.cropBox.x;
   718→            this.cropBox.height = y - this.cropBox.y;
   719→            break;
   720→        }
   721→      } else if (this.dragging) {
   722→        this.cropBox.x = this.cropBox.x + x - this.startX;
   723→        this.cropBox.y = this.cropBox.y + y - this.startY;
   724→        this.startX = x;
   725→        this.startY = y;
   726→      }
