   578→  drawCropBox() {
   579→    const ctx = this.context;
   580→    const cropBox = this.cropBox || {
   581→      x: 50,
   582→      y: 50,
   583→      width: 200,
   584→      height: 200,
   585→    };
   586→    const canvasWidth = this.canvas.width / pixelRatio;
   587→    const canvasHeight = this.canvas.height / pixelRatio;
   588→    ctx.clearRect(0, 0, canvasWidth, canvasHeight);
   589→    // 绘制遮罩
   590→    ctx.fillStyle = "rgba(0,0,0,0.5)";
   591→    // 上
   592→    ctx.fillRect(0, 0, canvasWidth, cropBox.y);
   593→    // 下
   594→    ctx.fillRect(
   595→      0,
   596→      cropBox.y + cropBox.height,
   597→      canvasWidth,
   598→      canvasHeight - (cropBox.y + cropBox.height)
   599→    );
   600→    // 左
   601→    ctx.fillRect(0, cropBox.y, cropBox.x, cropBox.height);
   602→    // 右
   603→    ctx.fillRect(
   604→      cropBox.x + cropBox.width,
   605→      cropBox.y,
   606→      canvasWidth - (cropBox.x + cropBox.width),
   607→      cropBox.height
