   609→    // 四角手柄
   610→    ctx.fillStyle = "#00c4ff";
   611→    const handleSize = 8;
   612→    const x = cropBox.x,
   613→      y = cropBox.y,
   614→      w = cropBox.width,
   615→      h = cropBox.height;
   616→    ctx.fillRect(
   617→      x - handleSize / 2,
   618→      y - handleSize / 2,
   619→      handleSize,
   620→      handleSize
   621→    );
   622→    ctx.fillRect(
   623→      x + w - handleSize / 2,
   624→      y - handleSize / 2,
   625→      handleSize,
   626→      handleSize
   627→    );
   628→    ctx.fillRect(
   629→      x - handleSize / 2,
   630→      y + h - handleSize / 2,
   631→      handleSize,
   632→      handleSize
   633→    );
   634→    ctx.fillRect(
   635→      x + w - handleSize / 2,
   636→      y + h - handleSize / 2,
   637→      handleSize,
   638→      handleSize
   639→    );
   640→  },
   641→  isInCorner(x, y) {
   642→    const box = this.cropBox;
   643→    const corners = {
   644→      tl: {
   645→        x: box.x,
   646→        y: box.y,
   647→      },
   648→      tr: {
   649→        x: box.x + box.width,
   650→        y: box.y,
   651→      },
   652→      bl: {
   653→        x: box.x,
   654→        y: box.y + box.height,
   655→      },
   656→      br: {
   657→        x: box.x + box.width,
   658→        y: box.y + box.height,
   659→      },
   660→    };
   661→    for (let [key, c] of Object.entries(corners)) {
   662→      if (Math.abs(x - c.x) < 20 && Math.abs(y - c.y) < 20) return key;
   663→    }
   664→    return null;
   665→  },
   666→  onCropTouchStart(e) {
   667→    const touches = e.touches;
   668→    if (touches.length === 1) {
   669→      const x = touches[0].x,
   670→        y = touches[0].y;
   671→      const corner = this.isInCorner(x, y);
   672→      if (corner) {
   673→        this.cropBox.resizing = true;
   674→        this.cropBox.resizeCorner = corner;
   675→      } else {
   676→        this.dragging = true;
   677→        this.startX = x;
   678→        this.startY = y;
   679→      }
   680→    } else if (touches.length === 2) {
   681→      const [a, b] = touches;
   682→      this.lastDistance = Math.hypot(b.x - a.x, b.y - a.y);
   683→      this.zooming = true;
   684→    }
   685→  },
