    if (this.data.palette == "mard-48") {
      current = 1;
    }
    if (this.data.palette == "mard-72") {
      current = 2;
    }
    if (this.data.palette == "mard-96") {
      current = 3;
    }
    const app = getApp();
    const urls = await app.getTempFileURLsAsync(paletteHelp);
    wx.previewImage({
      urls,
      current: urls[current],
    });
  },
  onFabricHelp() {
    wx.showModal({
      title: "如何选择绣布规格和绣线股数?",
      content: "11CT绣布格子粗一点，相应绣线股数就要多一点，14CT绣布格子细一些，绣线股数可以少一点。",
      showCancel: false,
      confirmText: "知道了",
    });
  },
  onFabricSizeHelp() {
    wx.showModal({
      title: "如何选择拼图大小",
      content: "拼图尺寸越大，效果越好，但是用豆量增加，制作时间也会增加",
      showCancel: false,
      confirmText: "知道了",
    });
  },
  switchTab(e) {
    const tab = e.currentTarget.dataset.tab;
    this.setData({
      activeTab: tab,
    });
  },
  async onPreviewEffect() {
    const app = getApp()
    try {
      const fileUrl = await app.getTempFileURLAsync(this.data.resultImage)
      wx.previewImage({
        urls: [fileUrl],
        //urls: [this.data.resultImage],
        fail: (res) => {
          console.error(res);
          wx.showModal({
            title: "预览错误",
            content: res.errMsg,
            showCancel: false,
            complete: (res) => {},
          });
        },
      });
    } catch (ex) {
      console.error(ex);
      wx.showModal({
        title: "预览错误",
        showCancel: false,
        content: ex.message,
        complete: (res) => {},
      });
    }
  },
  async onSaveToAlbum() {
    if (!this.data.resultImage) {
      wx.showToast({
        title: "请先生成效果图",
        icon: "none",
      });
      return;
    }
    const app = getApp();
    wx.showLoading({
      title: "保存中...",
    });

    const filePath = this.data.resultImage;
    try {
      const res = await app.saveImageToPhotosAlbumAsync(filePath);
      wx.hideLoading();
      if (res != "cancel") {
        const file = await app.downloadFileAsync(filePath, {
          h: 120
        })
        const savedFilePath = await app.saveFileAsync(file)
        let history = wx.getStorageSync('historyImgs') || [];
        history.push({
          palette: this.data.palette,
          width: this.data.targetHeight,
          height: this.data.targetHeight,
          effectUrl: this.data.resultImage,
          image: savedFilePath,
          date: new Date()
        })
        wx.setStorageSync('historyImgs', history);
        wx.showModal({
          title: "保存成功",
          content: "效果图已保存到相册，快去分享给朋友吧！",
          showCancel: false,
          confirmText: "知道了",
        });
      }
    } catch (ex) {
      console.error(ex);
      wx.hideLoading();
      wx.showModal({
        title: "错误",
        content: ex.message,
        showCancel: false,
        complete: (res) => {},
      });
    }
  },
  setTargetWidth(e) {
    const targetWidth = e.detail.value;
    const targetHeight = Math.round(targetWidth / this.cropRate);
    this.setData({
      targetWidth,
      targetHeight,
    });
  },
  setTargetHeight(e) {
    const targetHeight = e.detail.value;
    const targetWidth = Math.round(targetHeight * this.cropRate);
    this.setData({
      targetWidth,
      targetHeight,
    });
  },
  onCropImageLoad(e) {
    const {
      width,
      height
    } = e.detail;
    this.cropRate = (width * 1.0) / height;
    const targetHeight = Math.round(this.data.targetWidth / this.cropRate);
    const targetHeightCm = Math.round(
      (targetHeight / this.data.fabricType) * 2.54
    );
    const targetWidthCm = Math.round(
      (this.data.targetWidth / this.data.fabricType) * 2.54
    );
    this.setData({
      cropImageWidth: width,
      cropImageHeight: height,
      targetHeight,
      targetHeightCm,
      targetWidthCm,
    });
  },
  onSourceImageLoad(e) {
    const {
      width,
      height
    } = e.detail;
    this.sourceImageWidth = width;
    this.sourceImageHeight = height;
    const systemInfo = wx.getWindowInfo();
    const containerWidth = systemInfo.windowWidth - 60; // 减去左右padding
    const containerHeight = systemInfo.windowHeight - 200; // 减去上下空间

    // 计算图片在aspectFit模式下的实际显示尺寸
    const imgRatio = (width * 1.0) / height;
    const containerRatio = (containerWidth * 1.0) / containerHeight;
    let displayWidth, displayHeight;

    if (imgRatio > containerRatio) {
      // 图片宽度撑满容器
      displayWidth = containerWidth;
      displayHeight = containerWidth / imgRatio;
    } else {
      // 图片高度撑满容器
      displayHeight = containerHeight;
      displayWidth = containerHeight * imgRatio;
    }
    this.setData({
      canvasWidth: displayWidth,
      canvasHeight: displayHeight,
    });
    // 获取图片在屏幕中的实际位置和尺寸
    const query = wx.createSelectorQuery();
    query.select(".crop-original-image").boundingClientRect();
    query.selectViewport().scrollOffset();
    query.exec(async (res) => {
      if (res[0]) {
        console.log("image", res);
        const rect = res[0];
        this.setData({
          canvasWidth: rect.width,
          canvasHeight: rect.height,
          canvasTop: rect.top - 20,
          canvasLeft: rect.left - 15,
          originalImageInfo: {
            width: width,
            height: height,
          },
        });
        if (this.newImageSelected) {
          this.newImageSelected = false;
          this.cropBox = {
            x: (rect.width - 200) / 2,
            y: (rect.height - 200) / 2,
            width: 200,
            height: 200,
            resizing: false,
            resizeCorner: null,
          };
        }
        this.oldCropBox = {
          ...this.cropBox,
        };
        // 初始化Canvas

        this.canvas = null;
        await this.initCropCanvas(displayWidth, displayHeight);
        this.drawCropBox();
      }
    });
  },
  async onSelectImage() {
    const res = await wx.chooseMedia({
      count: 1,
      mediaType: ["image"],
      sourceType: ["album", "camera"],
      maxDuration: 30,
      camera: "back",
    });
    if (!res) {
      return;
    }
    this.newImageSelected = true;
    this.setData({
      sourceImage: res.tempFiles[0].tempFilePath,
      cropImage: res.tempFiles[0].tempFilePath,
      resultImage: null,
    });
  },
  onCropImage() {
    this.setData({
      showCrop: true,
    });
  },
  // 初始化裁剪画布
  async initCropCanvas() {
    if (this.canvas) {
      return;
    }
    const {
      canvas,
      context
    } = await getCanvasAsync("#cropCanvas");
    if (!canvas) {
      return;
    }
    this.canvas = canvas;
    this.context = context;
  },
  drawCropBox() {
    const ctx = this.context;
    const cropBox = this.cropBox || {
      x: 50,
      y: 50,
      width: 200,
      height: 200,
    };
    const canvasWidth = this.canvas.width / pixelRatio;
    const canvasHeight = this.canvas.height / pixelRatio;
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);
    // 绘制遮罩
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    // 上
    ctx.fillRect(0, 0, canvasWidth, cropBox.y);
    // 下
    ctx.fillRect(
      0,
      cropBox.y + cropBox.height,
      canvasWidth,
      canvasHeight - (cropBox.y + cropBox.height)
    );
    // 左
    ctx.fillRect(0, cropBox.y, cropBox.x, cropBox.height);
    // 右
    ctx.fillRect(
      cropBox.x + cropBox.width,
      cropBox.y,
      canvasWidth - (cropBox.x + cropBox.width),
      cropBox.height
    );
    // 四角手柄
    ctx.fillStyle = "#00c4ff";
    const handleSize = 8;
    const x = cropBox.x,
      y = cropBox.y,
      w = cropBox.width,
      h = cropBox.height;
    ctx.fillRect(
      x - handleSize / 2,
      y - handleSize / 2,
      handleSize,
      handleSize
    );
    ctx.fillRect(
      x + w - handleSize / 2,
      y - handleSize / 2,
      handleSize,
      handleSize
    );
    ctx.fillRect(
      x - handleSize / 2,
      y + h - handleSize / 2,
      handleSize,
      handleSize
    );
    ctx.fillRect(
      x + w - handleSize / 2,
      y + h - handleSize / 2,
      handleSize,
      handleSize
    );
  },
  isInCorner(x, y) {
    const box = this.cropBox;
    const corners = {
      tl: {
        x: box.x,
        y: box.y,
      },
      tr: {
        x: box.x + box.width,
        y: box.y,
      },
      bl: {
        x: box.x,
        y: box.y + box.height,
      },
      br: {
        x: box.x + box.width,
        y: box.y + box.height,
      },
    };
    for (let [key, c] of Object.entries(corners)) {
      if (Math.abs(x - c.x) < 20 && Math.abs(y - c.y) < 20) return key;
    }
    return null;
  },
  onCropTouchStart(e) {
    const touches = e.touches;
    if (touches.length === 1) {
      const x = touches[0].x,
        y = touches[0].y;
      const corner = this.isInCorner(x, y);
      if (corner) {
        this.cropBox.resizing = true;
        this.cropBox.resizeCorner = corner;
      } else {
        this.dragging = true;
        this.startX = x;
        this.startY = y;
      }
    } else if (touches.length === 2) {
      const [a, b] = touches;
      this.lastDistance = Math.hypot(b.x - a.x, b.y - a.y);
      this.zooming = true;
    }
  },
  async onCropTouchMove(e) {
    this.firstTap = null;
    const touches = e.touches;
    if (touches.length === 1) {
      const x = touches[0].x,
        y = touches[0].y;
      if (this.cropBox.resizing) {
        // 调整裁剪框大小
        const {
          resizeCorner,
          width,
          height
        } = this.cropBox;
        switch (resizeCorner) {
          case "tl":
            this.cropBox.width = this.cropBox.width - (x - this.cropBox.x);
            this.cropBox.height = this.cropBox.height - (y - this.cropBox.y);
            this.cropBox.x = x;
            this.cropBox.y = y;
            break;
          case "tr":
            this.cropBox.height = this.cropBox.height - (y - this.cropBox.y);
            this.cropBox.y = y;
            this.cropBox.width = x - this.cropBox.x;
            break;
          case "bl":
            this.cropBox.width = this.cropBox.width - (x - this.cropBox.x);
            this.cropBox.height = y - this.cropBox.y;
            this.cropBox.x = x;
            break;
          case "br":
            this.cropBox.width = x - this.cropBox.x;
            this.cropBox.height = y - this.cropBox.y;
            break;
        }
      } else if (this.dragging) {
        this.cropBox.x = this.cropBox.x + x - this.startX;
        this.cropBox.y = this.cropBox.y + y - this.startY;
        this.startX = x;
        this.startY = y;
      }
      //await drawImageAsync(this.canvas, this.context, this.sourceImg)
      this.drawCropBox();
    } else if (touches.length === 2 && this.zooming) {
      const [a, b] = touches;
      const distance = Math.hypot(b.x - a.x, b.y - a.y);
      const scaleChange = distance / this.lastDistance;
      this.scale *= scaleChange;
      this.lastDistance = distance;
      //await drawImageAsync(this.canvas, this.context, this.sourceImg)
      this.drawCropBox();
    }
  },
  onCropTouchEnd(e) {
    this.dragging = false;
    this.zooming = false;
    this.cropBox.resizing = false;
    this.cropBox.resizeCorner = null;
  },
  onCropCancel() {
    if (this.oldCropBox) {
      this.cropBox = this.oldCropBox;
    }
    this.setData({
      showCrop: false,
    });
  },
  async onCropConfirm() {
    console.log("crop box", this.cropBox);
    const scale = this.sourceImageWidth / this.data.canvasWidth;
    const cropImage = await exportCropBySource(
      this.data.sourceImage, {
        x: this.cropBox.x * scale,
        y: this.cropBox.y * scale,
        w: this.cropBox.width * scale,
        h: this.cropBox.height * scale,
      },
      this.sourceImageWidth,
      this.sourceImageHeight
    );
    this.setData({
      cropImage,
      showCrop: false,
    });
  },
  onMaxColorsChange(e) {
    this.setData({
      maxColors: e.currentTarget.dataset.value,
    });
  },
  onPaletteChange(e) {
    this.setData({
      palette: e.currentTarget.dataset.value,
    });
  },
  onFabricTypeChange(e) {
    this.setData({
      fabricType: e.currentTarget.dataset.value * 1,
    });
  },
  onThreadCountChange(e) {
    this.setData({
      threadCount: e.currentTarget.dataset.value * 1,
    });
  },
  async onGenerate() {
    if (!this.data.cropImage) {
      wx.showToast({
        title: "请先选择图片",
        icon: "none",
      });
      return;
    }
    try {
      wx.showLoading({
        title: "效果图生成中",
      });
      const resizeBase64 = await resizeImageAsync(
        this.data.cropImage,
        this.data.targetWidth,
        this.data.targetHeight,
        this.data.cropImageWidth,
        this.data.cropImageHeight
      );
      this.sourceImageBase64 = resizeBase64
      const res = await wx.cloud.callFunction({
        name: "genEffect",
        data: {
          image: resizeBase64,
          palette: this.data.palette,
        },
      });
      const result = res.result;
      this.setData({
        resultImage: result.effectUrl,
        activeTab: "result",
      });
      wx.hideLoading();
      wx.previewImage({
        urls: [result.effectUrl],
      });
    } catch (ex) {
      wx.hideLoading();
      wx.showModal({
        title: "错误",
        showCancel: false,
        content: ex.message,
        complete: (res) => {},
      });
      console.error(ex);
    }
  },
  async onBuyPaper() {
    wx.showLoading({
      title: '请等待',
    })
    const orderRes = await wx.cloud.callFunction({
      name: "createOrder",
      data: {
        productId,
        amount: 1,
        width: this.data.targetWidth,
        height: this.data.targetWidth,
        palette: this.data.palette,
        effectUrl: this.data.resultImage
      },
    });
    console.log(orderRes)
    if (orderRes.result.code != 0) {
      wx.hideLoading()
      wx.showModal({
        title: '错误',
        content: `创建订单错误:${orderRes.result.message||'未知原因'}`,
        showCancel: false,
        complete: (res) => {}
      })
      return
    }
    const app = getApp()
    try {
      await app.requestPaymentAsync(orderRes.result.data.payment)
      const payRes = await wx.cloud.callFunction({
        name: 'verifyPay',
        data: {
          orderId: orderRes.result.data.orderId
        }
      })
      wx.hideLoading()

    } catch (ex) {
      wx.hideLoading()
      console.error(ex)
      wx.showModal({
        title: '支付错误',
        content: ex.message,
        showCancel: false,
        complete: (res) => {}
      })
    }
  },
  /**
   * 生命周期函数--监听页面隐藏
   */
  onHide() {},

  /**
   * 生命周期函数--监听页面卸载
   */
  onUnload() {},

  /**
   * 页面相关事件处理函数--监听用户下拉动作
   */
  onPullDownRefresh() {},

  /**
   * 页面上拉触底事件的处理函数
   */
  onReachBottom() {},

  /**
   * 用户点击右上角分享
   */
  onShareAppMessage() {},
});

