{
  "name": "claude-code-sync",
  "displayName": "Claude Code Sync",
  "description": "Sync Claude Code conversation history within your project",
  "version": "0.0.1",
  "publisher": "your-publisher-name",
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Other"
  ],
  "activationEvents": [
    "onStartupFinished"
  ],
  "main": "./out/extension.js",
  "contributes": {
    "commands": [
      {
        "command": "claudeCodeSync.initialize",
        "title": "Initialize Claude Code Sync",
        "category": "Claude Code Sync"
      },
      {
        "command": "claudeCodeSync.openFolder",
        "title": "Open Claude Code History Folder",
        "category": "Claude Code Sync"
